<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['unique_identifier']);$s=db()->prepare('SELECT * FROM products WHERE unique_identifier=? AND user_id=? FOR UPDATE');db()->beginTransaction();try{$s->execute([$d['unique_identifier'],$u['id']]);$p=$s->fetch();if(!$p||$p['status']!=='available')fail('Available product not found',404);$price=(float)($d['selling_price']??$p['selling_price']);$q=db()->prepare('INSERT INTO sales(product_id,seller_id,customer_name,customer_phone,selling_price,cost_price,profit,payment_method,notes) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$p['id'],$u['id'],$d['customer_name']??null,$d['customer_phone']??null,$price,$p['cost_price'],profit($price,(float)$p['cost_price']),$d['payment_method']??'cash',$d['notes']??null]);db()->prepare("UPDATE products SET status='sold' WHERE id=?")->execute([$p['id']]);db()->commit();out(['success'=>true,'profit'=>profit($price,(float)$p['cost_price']),'message'=>'Sale recorded']);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();fail($e->getMessage(),400);}
